diff --git a/src/io/sales-import.js b/src/io/sales-import.js
new file mode 100644
index 0000000..42fdad0
--- /dev/null
+++ b/src/io/sales-import.js
@@ -0,0 +1,65 @@
+import { memoryStore } from "../db/store.js";
+import { isDate } from "../dates.js";
+import { consume } from "../domain/batches.js";
+import { getRecipe, scaled } from "../domain/recipes.js";
+import { AppError } from "../errors.js";
+import { parseCsv } from "./csv.js";
+
+const columns = ["ticket", "soldAt", "dishId", "qty"];
+const instant = /^\d{4}-\d{2}-\d{2}T(?:[01]\d|2[0-3]):[0-5]\d(?::[0-5]\d(?:\.\d+)?)?(?:Z|[+-]\d{2}:\d{2})$/;
+const csvLine = /^(?:"(?:[^"]|"")*"|[^",]*)(?:,(?:"(?:[^"]|"")*"|[^",]*))*$/;
+
+function invalid(row, reason) {
+  throw new AppError("bad_request", { reason: `row ${row}: ${reason}` });
+}
+
+/** Imports complete tickets atomically and counts newly sold portions. */
+export function importSales(store, text) {
+  const staged = memoryStore(store.data);
+  const existing = new Set(staged.data.sales.map((s) => s.ticket));
+  const imported = new Set();
+  let dishes = 0;
+  let header;
+  for (const [index, line] of text.split(/\r?\n/).entries()) {
+    if (!line.trim()) continue;
+    const row = index + 1;
+    if (!csvLine.test(line)) invalid(row, "malformed CSV");
+    const fields = parseCsv(line)[0].map((s) => s.trim());
+    if (!header) {
+      if (fields.length !== columns.length || !columns.every((c) => fields.includes(c)))
+        invalid(row, "expected ticket,soldAt,dishId,qty");
+      header = fields;
+      continue;
+    }
+    if (fields.length !== header.length) invalid(row, "wrong number of fields");
+    const sale = Object.fromEntries(header.map((key, i) => [key, fields[i]]));
+    const { ticket, soldAt } = sale;
+    const dishId = Number(sale.dishId);
+    const qty = Number(sale.qty);
+    if (!ticket) invalid(row, "missing ticket");
+    if (!instant.test(soldAt) || !Number.isFinite(Date.parse(soldAt)) || !isDate(soldAt.slice(0, 10)))
+      invalid(row, "invalid soldAt");
+    if (!Number.isSafeInteger(qty) || qty < 1) invalid(row, "invalid qty");
+    const dish = staged.data.dishes?.find((d) => d.id === dishId);
+    if (!dish) invalid(row, "unknown dishId");
+    if (existing.has(ticket)) continue;
+    const needs = scaled(getRecipe(staged, dish.recipeId), qty);
+    const at = new Date(soldAt).toISOString();
+    for (const { itemId, qty: amount } of needs) {
+      try {
+        consume(staged, itemId, amount, { at, ref: `sale:${ticket}` });
+      } catch (err) {
+        if (!(err instanceof AppError)) throw err;
+        if (err.code === "not_enough_stock")
+          throw new AppError("sale_shortage", { ...err.params, row });
+        invalid(row, err.code);
+      }
+    }
+    staged.data.sales.push({ ticket, soldAt: at, dishId, qty, ingredients: needs });
+    imported.add(ticket);
+    dishes += qty;
+  }
+  if (!header) invalid(1, "missing header");
+  store.data = staged.data;
+  return { tickets: imported.size, dishes };
+}
